from copy import copy
from datetime import datetime
from pathlib import Path

from openpyxl import load_workbook
from docx import Document

TEMPLATE = Path('/root/Outbound_Audit_Template.xlsx')
MANIFEST = Path('/root/Manifest_Plan.xlsx')
SCANS = Path('/root/Dock_Scan_Log.xlsx')
OUT_XLSX = Path('/root/Outbound_Load_Audit.xlsx')
OUT_DOCX = Path('/root/Outbound_Load_Brief.docx')

REQUIRED_FORMATTED_HEADERS = [
    'Shipment ID', 'Carton ID', 'Planned Zone', 'Route',
    'Expected Weight', 'Hazmat Flag', 'Carrier', 'Wave',
    'Missing Load Scan', 'Zone Mismatch', 'Total Errors', 'Error Summary'
]
SUMMARY_HEADERS = ['Route', 'Shipment ID', 'Missing Load Scans', 'Zone Mismatches', 'Total Errors']


def normalize(v):
    return '' if v is None else str(v).strip().lower()


def parse_ts(v):
    if isinstance(v, datetime):
        return v
    if v is None:
        return datetime.min
    if isinstance(v, str):
        try:
            return datetime.fromisoformat(v)
        except ValueError:
            return datetime.min
    return datetime.min


def rows_from_sheet(path):
    wb = load_workbook(path, data_only=True)
    ws = wb[wb.sheetnames[0]]
    rows = [list(r) for r in ws.iter_rows(values_only=True)]
    return rows


def clear_sheet(ws):
    # Clear values only; preserve sheet object and broad formatting/settings.
    for row in ws.iter_rows():
        for cell in row:
            cell.value = None


def snapshot_sheet(ws):
    snap = []
    for row in ws.iter_rows():
        row_snap = []
        for c in row:
            row_snap.append((c.coordinate, c.value, c.data_type, c.number_format, copy(c.font), copy(c.fill), copy(c.border), copy(c.alignment), copy(c.protection)))
        snap.append(row_snap)
    return snap


def build_workbook():
    if not TEMPLATE.exists():
        raise FileNotFoundError(TEMPLATE)
    wb = load_workbook(TEMPLATE)
    if 'Overview' not in wb.sheetnames:
        raise RuntimeError('Template missing Overview sheet')
    overview_before = snapshot_sheet(wb['Overview'])

    for name in ['RawData', 'Formatted Data', 'Summary']:
        if name in wb.sheetnames:
            ws = wb[name]
            clear_sheet(ws)
        else:
            ws = wb.create_sheet(name)

    manifest_rows = rows_from_sheet(MANIFEST)
    manifest_headers = manifest_rows[0]
    manifest_data = manifest_rows[1:]

    raw = wb['RawData']
    for r_idx, row in enumerate(manifest_rows, start=1):
        for c_idx, value in enumerate(row, start=1):
            raw.cell(row=r_idx, column=c_idx, value=value)

    # Build scan lookup from LOADED rows, latest by timestamp column when present.
    scan_rows = rows_from_sheet(SCANS)
    scan_headers = scan_rows[0]
    scan_idx = {h: i for i, h in enumerate(scan_headers)}
    for required in ['Shipment ID', 'Carton ID', 'Scanned Zone', 'Status']:
        if required not in scan_idx:
            raise RuntimeError(f'Dock scan log missing required column {required!r}; headers={scan_headers!r}')
    timestamp_col = None
    for h in scan_headers:
        if isinstance(h, str) and ('timestamp' in h.lower() or 'time' in h.lower() or 'sequence' in h.lower() or h.lower() in {'seq', 'scan seq'}):
            timestamp_col = h
            break

    lookup = {}
    for order, row in enumerate(scan_rows[1:], start=1):
        if row[scan_idx['Status']] != 'LOADED':
            continue
        key = (row[scan_idx['Shipment ID']], row[scan_idx['Carton ID']])
        if timestamp_col:
            sort_key = (parse_ts(row[scan_idx[timestamp_col]]), order)
        else:
            sort_key = (order,)
        existing = lookup.get(key)
        if existing is None or sort_key >= existing[0]:
            lookup[key] = (sort_key, row)

    m_idx = {h: i for i, h in enumerate(manifest_headers)}
    for h in REQUIRED_FORMATTED_HEADERS[:8]:
        if h not in m_idx:
            raise RuntimeError(f'Manifest missing required column {h!r}; headers={manifest_headers!r}')

    formatted = wb['Formatted Data']
    for c_idx, h in enumerate(REQUIRED_FORMATTED_HEADERS, start=1):
        formatted.cell(row=1, column=c_idx, value=h)

    formatted_records = []
    for out_r, row in enumerate(manifest_data, start=2):
        base = [row[m_idx[h]] for h in REQUIRED_FORMATTED_HEADERS[:8]]
        key = (base[0], base[1])
        kept = lookup.get(key)
        if kept is None:
            missing = 1
            mismatch = 0
        else:
            missing = 0
            scanned_zone = kept[1][scan_idx['Scanned Zone']]
            mismatch = 1 if scanned_zone != base[2] else 0
        total = int(missing) + int(mismatch)
        if total == 0:
            summary = 'None'
        elif missing == 1 and mismatch == 0:
            summary = 'Missing Load Scan'
        elif missing == 0 and mismatch == 1:
            summary = 'Zone Mismatch'
        else:
            summary = 'Missing Load Scan, Zone Mismatch'
        values = base + [missing, mismatch, total, summary]
        for c_idx, value in enumerate(values, start=1):
            formatted.cell(row=out_r, column=c_idx, value=value)
        formatted_records.append(dict(zip(REQUIRED_FORMATTED_HEADERS, values)))

    grouped = defaultdict(lambda: {'Missing Load Scans': 0, 'Zone Mismatches': 0, 'Total Errors': 0})
    for rec in formatted_records:
        key = (rec['Route'], rec['Shipment ID'])
        grouped[key]['Missing Load Scans'] += rec['Missing Load Scan']
        grouped[key]['Zone Mismatches'] += rec['Zone Mismatch']
        grouped[key]['Total Errors'] += rec['Total Errors']

    included = []
    for (route, shipment), vals in grouped.items():
        if vals['Total Errors'] > 0:
            included.append([route, shipment, vals['Missing Load Scans'], vals['Zone Mismatches'], vals['Total Errors']])
    included.sort(key=lambda x: (str(x[0]), str(x[1])))

    summary_ws = wb['Summary']
    for c_idx, h in enumerate(SUMMARY_HEADERS, start=1):
        summary_ws.cell(row=1, column=c_idx, value=h)
    for r_idx, row in enumerate(included, start=2):
        for c_idx, value in enumerate(row, start=1):
            summary_ws.cell(row=r_idx, column=c_idx, value=value)
    totals = [sum(r[2] for r in included), sum(r[3] for r in included), sum(r[4] for r in included)]
    gt_row = len(included) + 2
    grand_total = ['Grand Total', '-', totals[0], totals[1], totals[2]]
    for c_idx, value in enumerate(grand_total, start=1):
        summary_ws.cell(row=gt_row, column=c_idx, value=value)

    overview_after = snapshot_sheet(wb['Overview'])
    if overview_after != overview_before:
        raise RuntimeError('Overview changed before save')

    wb.save(OUT_XLSX)
    return included, grand_total


def verify_workbook(expected_overview_snapshot):
    template_wb = load_workbook(TEMPLATE)
    expected_overview = snapshot_sheet(template_wb['Overview'])
    audit_wb = load_workbook(OUT_XLSX, data_only=False)
    actual_overview = snapshot_sheet(audit_wb['Overview'])
    if actual_overview != expected_overview:
        raise RuntimeError('Saved Overview content/style does not match template exactly')

    raw = audit_wb['RawData']
    formatted = audit_wb['Formatted Data']
    summary = audit_wb['Summary']
    manifest_rows = rows_from_sheet(MANIFEST)

    assert raw.max_row == len(manifest_rows), (raw.max_row, len(manifest_rows))
    assert raw.max_column == len(manifest_rows[0]), (raw.max_column, len(manifest_rows[0]))
    assert [formatted.cell(1, c).value for c in range(1, 13)] == REQUIRED_FORMATTED_HEADERS
    assert formatted.max_column == 12
    assert [summary.cell(1, c).value for c in range(1, 6)] == SUMMARY_HEADERS
    assert summary.max_column == 5
    assert summary.cell(summary.max_row, 1).value == 'Grand Total'

    data_summary = [[summary.cell(r, c).value for c in range(1, 6)] for r in range(2, summary.max_row)]
    assert data_summary == sorted(data_summary, key=lambda x: (str(x[0]), str(x[1])))
    for row in formatted.iter_rows(min_row=2, min_col=9, max_col=12, values_only=False):
        assert row[0].data_type != 'f' and row[1].data_type != 'f' and row[2].data_type != 'f' and row[3].data_type != 'f'
        assert isinstance(row[0].value, int) and isinstance(row[1].value, int) and isinstance(row[2].value, int)
        assert row[3].value in {'None', 'Missing Load Scan', 'Zone Mismatch', 'Missing Load Scan, Zone Mismatch'}

    print('Workbook verification passed.')
    print('Saved sheet names:', audit_wb.sheetnames)
    print('RawData rows/columns:', raw.max_row, raw.max_column)
    print('Formatted Data headers:', [formatted.cell(1, c).value for c in range(1, 13)])
    print('Summary contents:')
    for r in range(1, summary.max_row + 1):
        print([summary.cell(r, c).value for c in range(1, 6)])


def create_brief():
    wb = load_workbook(OUT_XLSX, data_only=True)
    ws = wb['Summary']
    rows = [[ws.cell(r, c).value for c in range(1, 6)] for r in range(2, ws.max_row + 1)]
    data_rows = [r for r in rows if r[0] != 'Grand Total']
    gt = rows[-1]
    top_shipments = sorted(data_rows, key=lambda r: (-int(r[4]), str(r[1])))[:2]
    top_text = ', '.join(f'{r[1]} ({r[4]} total errors)' for r in top_shipments)

    doc = Document()
    doc.add_heading('Outbound Load Audit Brief', level=1)
    p = doc.add_paragraph()
    p.add_run(
        f'This audit checks each planned outbound carton against dock load scans. '
        f'Missing Load Scan means a carton in the manifest was never scanned as loaded at the dock, while Zone Mismatch means a carton was scanned as loaded but in a different zone than planned. '
        f'The completed audit identified {gt[2]} Missing Load Scans, {gt[3]} Zone Mismatches, and {gt[4]} Total Errors. '
        f'The highest-priority Shipment IDs by exception volume are {top_text}, and these loads should be reviewed first for operational impact. '
        f'Recommended actions include implementing real-time zone validation alerts during loading and retraining dock staff on zone assignment protocols before the next outbound wave.'
    )
    doc.save(OUT_DOCX)
    return gt, top_shipments


if __name__ == '__main__':
    included, grand_total = build_workbook()
    verify_workbook(None)
    gt, top = create_brief()
    print('Brief saved:', OUT_DOCX)
    print('Grand Total:', gt)
    print('Top shipments:', top)
